from gurobipy import Model, GRB, quicksum

def build_and_solve():
    shelves = []
    shelf_caps = {}
    products = []
    product_vals = {}
    product_wgts = {}
    for rec in LEGACY_RECORDS:
        src = rec['source']
        vals = rec['values']
        if src.endswith('capacity.csv'):
            shelf_id = vals['ShelfID']
            cap = float(vals['Capacity'])
            shelves.append(shelf_id)
            shelf_caps[shelf_id] = cap
        elif src.endswith('products.csv'):
            pname = vals['ProductName']
            idx = len(products) + 1
            products.append(pname)
            product_vals[pname] = float(vals['Value'])
            product_wgts[pname] = float(vals['Weight'])
    if len(shelves) != 10:
        raise ValueError('Expected 10 shelves, got %d' % len(shelves))
    if len(products) != 20:
        raise ValueError('Expected 20 products, got %d' % len(products))
    for s in shelves:
        if s not in shelf_caps:
            raise ValueError(f'Missing capacity for shelf {s}')
    for p in products:
        if p not in product_vals or p not in product_wgts:
            raise ValueError(f'Missing value/weight for product {p}')
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = m.addVars(shelves, products, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(quicksum((product_vals[p] * x_vars[s, p] for s in shelves for p in products)), GRB.MAXIMIZE)
    for s in shelves:
        m.addConstr(quicksum((product_wgts[p] * x_vars[s, p] for p in products)) <= shelf_caps[s], name=f'cap_{s}')
    first_product = products[0]
    m.addConstr(quicksum((x_vars[s, first_product] for s in shelves)) >= 5, name='min_smartphone')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print('ObjVal', m.ObjVal)
        for s in shelves:
            for p in products:
                v = x_vars[s, p]
                print(v.VarName, v.X)
    else:
        print('Solver status:', m.Status)
    return m
m = build_and_solve()